  canAt(-36, 12); canAt(20, 16); canAt(2, 24, true); canAt(33, 26);

  // ---------- Dumpster hideout (bank your loot here) ----------
  const hideout = new THREE.Group();
  const dump = new THREE.Mesh(new THREE.BoxGeometry(5, 2.4, 2.6), mat(metalT, 0x2f6b4f));
  dump.position.y = 1.3;
