+    let tmin = 0, tmax = 1;
+    if (Math.abs(dx) < 1e-8) {
+      if (x1 < b.minX || x1 > b.maxX) continue;
+    } else {
+      let t1 = (b.minX - x1) / dx, t2 = (b.maxX - x1) / dx;
+      if (t1 > t2) [t1, t2] = [t2, t1];
+      tmin = Math.max(tmin, t1); tmax = Math.min(tmax, t2);
+      if (tmin > tmax) continue;
+    }
+    if (Math.abs(dz) < 1e-8) {
+      if (z1 < b.minZ || z1 > b.maxZ) continue;
+    } else {
