+      const nx = Math.max(o.minX, Math.min(x, o.maxX));
+      const nz = Math.max(o.minZ, Math.min(z, o.maxZ));
+      const dx = x - nx, dz = z - nz;
+      const d2 = dx * dx + dz * dz;
+      if (d2 < r * r) {
