+  // window-event ground glow
+  const glow = new THREE.Mesh(new THREE.CircleGeometry(5.2, 24), new THREE.MeshBasicMaterial({ color: 0xffd88a, transparent: true, opacity: 0, depthWrite: false }));
+  glow.rotation.x = -Math.PI / 2;
