+let policeCar = null, carX = -40, carDir = 1;
+const lootItems = []; // {kind, value, group, x, z, taken}
+let seagull = null; // {api, state, target, t, from}
+let seagullTimer = 18;
+let windowEvent = null; // {win, t, circle}
+let windowTimer = 14;
