+    sfx.lose();
+    overlay.innerHTML = `
+      <h2>THE SUN CAME UP ☀️</h2>
+      <p>Only <b style="color:#ffd23f">${banked}</b> of ${goal} banked before dawn.<br>
+      The crew scattered into the hedges. Tonight, we go again.</p>
