+}
+
+function updateCarryHUD() {
+  $('carry-val').textContent = carried.length;
+  $('hud-carry').style.borderColor = carried.length >= MAX_CARRY ? 'rgba(255,90,90,0.8)' : 'rgba(140,170,255,0.25)';
