+  get carriedCount() { return carried.length; },
+  get nightTime() { return nightTime; },
+  get guards() { return guards.map((g) => ({ mode: g.mode, alert: g.alert, x: g.pos.x, z: g.pos.z })); },
+  get loot() { return lootItems.map((l) => ({ x: l.x, z: l.z, kind: l.kind })); },
