+      we.t = 5;
+      we.win = world.windows[Math.floor(Math.random() * world.windows.length)];
+      we.cx = we.win.pos.x + we.win.dir.x * 3.4;
+      we.cz = we.win.pos.z + we.win.dir.z * 3.4;
