+    }
+    return;
+  }
+  we.t -= dt;
+  const pulse = 0.32 + Math.sin(performance.now() / 130) * 0.08;
+  we.circle.material.opacity = we.t > 0.6 ? pulse : pulse * (we.t / 0.6);
