+  for (const l of lootItems) {
+    if (l.taken) continue;
+    if (Math.hypot(l.x - playerPos.x, l.z - playerPos.z) < 1.15) {
+      if (l.kind === 'pizza') {
+        l.taken = true;
+        scene.remove(l.group);
+        frenzyUntil = now + 6;
+        sfx.frenzy();
