+        toast('📺 THE GOLDEN TV! Haul it home… slowly.', 3000);
+        camShake = Math.max(camShake, 0.25);
+      }
+      (l.kind === 'coin' ? sfx.coin : l.kind === 'gem' || l.kind === 'ring' || l.kind === 'tv' ? sfx.gem : sfx.munch)();
