+  if (speed > 0) {
+    let nx = playerPos.x + mx * speed * dt;
+    let nz = playerPos.z + mz * speed * dt;
+    [nx, nz] = circleVsObstacles(nx, nz, PLAYER_RADIUS);
+    playerPos.x = nx; playerPos.z = nz;
+  }
