+// ---------------------------------------------------------------- Camera
+function updateCamera(dt) {
+  const portrait = window.innerHeight > window.innerWidth;
+  const dy = portrait ? 16 : 12;
+  const dz = portrait ? 12.5 : 12.5;
+  tmpV.set(playerPos.x, dy, playerPos.z + dz);
