+  if (state === 'playing') {
+    updatePlayer(dt);
+    updateGuards(dt);
+    updatePoliceCar(dt);
+    updateSeagull(dt);
+    updateWindowEvent(dt);
+    updateDawn(dt);
+  } else if (state === 'caught') {
+    caughtTimer -= dt;
+    updateGuards(dt * 0.3);
+    updatePoliceCar(dt);
+    if (caughtTimer <= 0) {
+      playerPos.set(0, 0, 26);
+      player.group.position.copy(playerPos);
+      vignette.style.opacity = '0';
+      state = 'playing';
+    }
+    updateDawn(dt);
+  } else if (state === 'results') {
+    updatePoliceCar(dt);
+    for (const g of guards) g.api.animate(dt, 0.1);
+  }
+
+  updateCamera(dt);
+  renderer.render(scene, camera);
+}
