+          const pl = x - o.minX, pr = o.maxX - x, pt = z - o.minZ, pb = o.maxZ - z;
+          const m = Math.min(pl, pr, pt, pb);
+          if (m === pl) x = o.minX - r; else if (m === pr) x = o.maxX + r;
