+    const ahead = (playerPos.x - carX) * carDir;
+    if (Math.abs(playerPos.z - world.roadZ) < 4 && ahead > 0 && ahead < 12) {
+      for (const g of guards) g.alert = Math.min(100, g.alert + 240 * dt);
