+function worldToScreen(v3) {
+  const v = v3.clone().project(camera);
+  return [(v.x * 0.5 + 0.5) * window.innerWidth, (-v.y * 0.5 + 0.5) * window.innerHeight];
+}
+
+// ---------------------------------------------------------------- Setup
+function spawnLoot(count) {
+  for (const l of lootItems) scene.remove(l.group);
