+    const kind = pickLootKind();
+    const [x, z] = randomLootSpot();
+    const group = makeLoot(kind);
+    group.position.set(x, 0, z);
+    scene.add(group);
+    lootItems.push({ kind, value: LOOT_TYPES[kind].value, group, x, z, taken: false });
+  }
+}
