+    } else {
+      speed = 1.6;
+      const ta = Math.atan2(dx, dz);
+      let da = ta - d.angle;
+      while (da > Math.PI) da -= Math.PI * 2;
+      while (da < -Math.PI) da += Math.PI * 2;
+      d.angle += da * Math.min(1, dt * 3);
