+  if (state === 'playing') {
+    updatePlayer(dt);
+    updateGuards(dt);
+    updatePoliceCar(dt);
+    updateDog(dt);
+    updateSeagull(dt);
+    updateWindowEvent(dt);
+    updateDawn(dt);
+  } else if (state === 'caught') {
