+  updateCarryHUD();
+  const who = source === 'dog' ? 'The hound ran you off!' : source === 'car' ? 'Caught in the headlights!' : 'The guard shooed you off!';
+  toast('Busted! 🚨 ' + (dropCount ? 'You dropped some loot!' : who), 3000);
