+
+function startNight(n) {
+  night = n;
+  goal = 120 + (n - 1) * 110;
+  nightTime = 0;
+  banked = 0;
+  for (const c of carried) player.lootAnchor.remove(c.mesh);
+  carried.length = 0;
+  playerPos.set(0, 0, 26);
+  playerAngle = Math.PI;
