+  updateCamera(dt);
+  renderer.render(scene, camera);
+}
+
+// ---------------------------------------------------------------- Boot
+const playBtn = document.getElementById('play-btn');
+const statusEl = document.getElementById('loading-status');
+let worldReady = false, worldLoading = false;
