+async function ensureWorld() {
+  if (worldReady || worldLoading) return;
+  worldLoading = true;
+  statusEl.textContent = 'Casing the joint…';
+  try {
+    await setupGame();
+    worldReady = true;
+    statusEl.textContent = '';
+  } catch (e) {
+    statusEl.textContent = 'Load hiccup — tap START to retry.';
+    worldLoading = false;
+    console.error(e);
+  }
+}
+
+ensureWorld();
+
+// show best run on the title screen, if any
+try {
+  const best = +(localStorage.getItem('rh-best-night') || 0);
