+    p.textContent = `🏆 Best run: cleared Night ${best}`;
+    statusEl.parentNode.insertBefore(p, statusEl.nextSibling);
+  }
+} catch (e) { /* private mode */ }
+
+playBtn.addEventListener('click', async () => {
